#!/usr/bin/env node
/**
 * cloudflare-domain.ts - Automatically extract Cloudflare zone & domain from cert.pem
 *
 * Reads the origin certificate token generated by `cloudflared tunnel login` (~/.cloudflared/cert.pem)
 * and queries the Cloudflare API to extract the active domain name.
 */

import { readFileSync, existsSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

function printHelp() {
  console.log(`Cloudflare Domain Extractor (overskill)
Automatically extract custom domain information from cloudflared login cert.

USAGE
  node scripts/cloudflare-domain.ts [options]
  ./scripts/cloudflare-domain.ts [options]

OPTIONS
  --cert <path>     Path to cloudflared cert.pem (default: ~/.cloudflared/cert.pem)
  --tld             Output formatted for PORTLESS_TLD ("localhost,<domain>")
  --json            Output structured JSON ({ domain, zoneId, accountId })
  -h, --help        Show this help reference

EXAMPLES
  # Get plain domain name:
  node scripts/cloudflare-domain.ts
  # Output: example.com

  # Configure Fish shell in one command:
  set -Ux PORTLESS_TLD (node scripts/cloudflare-domain.ts --tld)
`);
}

async function main() {
  const args = process.argv.slice(2);
  if (args.includes('-h') || args.includes('--help')) {
    printHelp();
    process.exit(0);
  }

  let certPath = join(homedir(), '.cloudflared', 'cert.pem');
  const certIdx = args.indexOf('--cert');
  if (certIdx !== -1 && args[certIdx + 1]) {
    certPath = args[certIdx + 1];
  }

  if (!existsSync(certPath)) {
    console.error(`Error: Cloudflare certificate not found at '${certPath}'.`);
    console.error(`Please run 'cloudflared tunnel login' first.`);
    process.exit(1);
  }

  const raw = readFileSync(certPath, 'utf8');
  // Strip header/footer lines and whitespace
  const base64Token = raw
    .split('\n')
    .filter(line => !line.startsWith('-----') && line.trim().length > 0)
    .join('')
    .trim();

  let tokenData: { zoneID?: string; accountID?: string; apiToken?: string };
  try {
    const decoded = Buffer.from(base64Token, 'base64').toString('utf8');
    tokenData = JSON.parse(decoded);
  } catch (err) {
    console.error(`Error: Failed to decode Argo Tunnel token from '${certPath}':`, err);
    process.exit(1);
  }

  const { zoneID, accountID, apiToken } = tokenData;
  if (!zoneID || !apiToken) {
    console.error(`Error: Certificate token does not contain required zoneID or apiToken.`);
    process.exit(1);
  }

  try {
    const res = await fetch(`https://api.cloudflare.com/client/v4/zones/${zoneID}`, {
      headers: {
        Authorization: `Bearer ${apiToken}`,
        'Content-Type': 'application/json',
      },
    });

    if (!res.ok) {
      console.error(`Error: Cloudflare API returned status ${res.status}: ${res.statusText}`);
      const text = await res.text();
      console.error(text);
      process.exit(1);
    }

    const data = (await res.json()) as { result?: { name?: string } };
    const domainName = data.result?.name;
    if (!domainName) {
      console.error(`Error: Cloudflare API response did not contain a zone name.`);
      process.exit(1);
    }

    if (args.includes('--json')) {
      console.log(
        JSON.stringify(
          {
            domain: domainName,
            zoneId: zoneID,
            accountId: accountID,
          },
          null,
          2
        )
      );
    } else if (args.includes('--tld')) {
      console.log(`localhost,${domainName}`);
    } else {
      console.log(domainName);
    }
  } catch (err) {
    console.error('Error fetching zone details from Cloudflare API:', err);
    process.exit(1);
  }
}

main();
